#!/bin/sh
# Build stock.txt from the day's movements log.
# Reporting rules (HANDOFF.md): every catalog SKU must appear in the report,
# including SKUs with no movements that day. Each SKU is listed once with its
# net count (receipts minus shipments); SKUs with no movements net to 0.
awk 'BEGIN { for (i = 1; i <= 9; i++) sku["SKU-" i] }
     { net[$1] += ($2 == "receipt" ? $3 : -$3) }
     END { for (s in sku) print s, (s in net ? net[s] : 0) }' \
    movements.log | sort > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in the day's movements, plus catalog SKUs with no movements
# that day (SKU-9 is in the catalog), each with its net count (receipts minus
# shipments; 0 when there are no movements).
{
  awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3) }
       END { for (s in net) print s, net[s] }' movements.log
  printf 'SKU-9 0\n'
} | sort -u > stock.txt
